examples.fragment:
@pattern bass_line | instrument: bass/electric_bass, preset: punchy_bass
  events:
    Bb1 8th f articulation=staccato
    @1.0 Db2 q mf
    rest 8th

@phrase chords [9:1:0 - 11:1:0]
  @0.0 G4 q mf, G5 q mf
  @1.0 C4 q. mf, E4 q. mf, G4 q. mf
  @2.0 [D4 F4 A4] h mp, C5 q pp

@track lead | preset: tone, instrument: synth/lead_saw
  @phrase slide [1:1 - 3:1]
    C4 q mf gliss
    G4 h mf
    A4 q mf gliss=run
    E5 q mf

@track drums | instrument: drums/drumkit
  @pattern groove [1:1 - 9:1] x8
    kick 1:0 f
    snare 2:0 f
    hat_closed 1:2 mp articulation=closed

@kit basic
  max_voices: 32
  pad kick  | note: C2, gain: -2dB, choke: 1
  pad snare | note: D2, decay: 0.2s
  layer kick | low: 1, high: 127, sample: "samples/kick.wav"

@track drums | instrument: drums/drumkit, preset: basic
  @pattern beat [1:1 - 2:1]
    kick 1:0 ff
    snare 2:0 mf

@audio_clip intro [1:1 - 5:1] | track: tape
  file: "media/intro.flac"  offset: 250ms  gain: -3dB  fade_in: 5ms
@track tape | instrument: audio/clip

@track lead | instrument: synth/lead_saw
  effects:
    - eq: high_gain=0dB@8kHz
  automation: brightness {1:1=20%, 5:1=90%}
  automation: eq.high_gain [ppq=480] smoothing=25ms {1:1=-6dB, 9:1=+6dB curve=half_sine}

@master
  effects:
    - eq: low_shelf=+1dB@60Hz
    - limiter: ceiling=-0.3dB
  gain_automation: linear [1:1 - 9:1] {1:1=1, 5:1=0.5, 8:1=1}

@phrase pedalled [1:1 - 3:1]
  @0 pedal down
  C4 w mf
  @6 pedal up

@phrase swell [1:1 - 5:1]
  @0.0 cresc
  @0 C4 w pp
  @4 C4 w
  @8 C4 w
  @12 C4 w f
